import{_ as r,o as e,c as n,a3 as d}from"./chunks/framework.B9qR_F1m.js";const h=JSON.parse('{"title":"Begriffe","description":"","frontmatter":{},"headers":[],"relativePath":"referenz/begriffe.md","filePath":"referenz/begriffe.md"}'),i={name:"referenz/begriffe.md"};function a(o,t,s,g,l,u){return e(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="begriffe" tabindex="-1">Begriffe <a class="header-anchor" href="#begriffe" aria-label="Permalink to &quot;Begriffe&quot;">​</a></h1><p>Shardwing nutzt die Begriffe der USAF und NATO, wie sie auch in DCS und in den meisten virtuellen Staffeln üblich sind.</p><h2 id="planung-und-briefing" tabindex="-1">Planung und Briefing <a class="header-anchor" href="#planung-und-briefing" aria-label="Permalink to &quot;Planung und Briefing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Paket</strong> (Package)</td><td>Alle Flights, die zusammen einen Auftrag fliegen</td></tr><tr><td><strong>Flight</strong></td><td>Eine Gruppe von meist zwei oder vier Flugzeugen unter einem Callsign</td></tr><tr><td><strong>Lead / Wingman</strong></td><td>Führer des Flights bzw. die anderen Flugzeuge</td></tr><tr><td><strong>Lineup Card</strong></td><td>Kneeboard-Hauptseite eines Flights: Zeiten, Besatzung, Fuel, Diverts, Beladung</td></tr><tr><td><strong>Comm Card</strong></td><td>Funkbelegung des Jets auf einer Seite</td></tr><tr><td><strong>Comm Plan</strong></td><td>Funkplan des Pakets: Netze, Frequenzen, Preset-Kanäle</td></tr><tr><td><strong>SPINS</strong></td><td>Special Instructions: Platzverfahren, Luftraum, ROE, IFF …</td></tr><tr><td><strong>Abnormals</strong></td><td>Verfahren für Notfälle in der Formation</td></tr><tr><td><strong>Joker / Bingo</strong></td><td>Kraftstoffgrenzen: Joker = Zeit ans Heimkehren zu denken, Bingo = jetzt zurück</td></tr><tr><td><strong>Divert</strong></td><td>Ausweichflugplatz</td></tr><tr><td><strong>Mission Designer</strong></td><td>Wer die Mission baut und in Shardwing alles darf</td></tr><tr><td><strong>Slot</strong></td><td>Auf dem Shardwing-Server: Platz für eine Mission einer Staffel. Wird die Mission gelöscht oder läuft ab, ist er wieder frei (<a href="/gemeinsam/staffeln">Staffeln</a>)</td></tr><tr><td><strong>Staffel-Schlüssel</strong></td><td>Code wie <code>K4P9-X2T7-M8QW</code>, mit dem Mitglieder einer Staffel Missionen über Teilen hochladen</td></tr><tr><td><strong>Staffel-Link</strong></td><td>Link zum Staffel-Panel, nur für die Staffelführung</td></tr></tbody></table><h2 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>H-Hour</strong></td><td>Bezugszeit des Pakets, alle Zeiten als H±Minuten</td></tr><tr><td><strong>TOT</strong></td><td>Time on Target – Zeit über dem Ziel, mit Fenster</td></tr><tr><td><strong>Vul</strong></td><td>Vulnerability Window – Zeitraum, in dem ein Flight auf Station sein muss (CAP, Escort, Tanker)</td></tr><tr><td><strong>Push</strong></td><td>Zeitpunkt, an dem ein Flight vom Sammelpunkt Richtung Ziel aufbricht</td></tr><tr><td><strong>TOS</strong></td><td>Time over Steerpoint</td></tr><tr><td><strong>ETA</strong></td><td>Estimated Time of Arrival laut Route</td></tr><tr><td><strong>AAR</strong></td><td>Air-to-Air Refueling – Luftbetankung</td></tr><tr><td><strong>Boom / Drogue</strong></td><td>Betankung per Ausleger (F-16) bzw. Schlauch mit Korb (F/A-18)</td></tr><tr><td><strong>Deconfliction</strong></td><td>Sicherstellen, dass sich Flights nicht in die Quere kommen</td></tr><tr><td><strong>Höhenblock</strong></td><td>Höhenband, das einem Flight gehört, z. B. FL200–220</td></tr></tbody></table><h2 id="navigation-und-avionik" tabindex="-1">Navigation und Avionik <a class="header-anchor" href="#navigation-und-avionik" aria-label="Permalink to &quot;Navigation und Avionik&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>DTC</strong></td><td>Data Transfer Cartridge – Datei, aus der der Jet Steerpoints, Funk, CMDS lädt</td></tr><tr><td><strong>Steerpoint / Waypoint</strong></td><td>Navigationspunkt (F-16 bzw. F/A-18)</td></tr><tr><td><strong>Bullseye (BE)</strong></td><td>Gemeinsamer Bezugspunkt für Positionsangaben als Peilung/Distanz</td></tr><tr><td><strong>Geo Lines</strong></td><td>Linien auf dem HSD der F-16, z. B. FLOT</td></tr><tr><td><strong>MEZ</strong></td><td>Missile Engagement Zone – Bedrohungsring</td></tr><tr><td><strong>CMDS</strong></td><td>Countermeasures Dispenser System – Chaff/Flare-Programme</td></tr><tr><td><strong>OA1 / OA2</strong></td><td>Offset Aimpoints in der F-16</td></tr><tr><td><strong>VIP / VRP</strong></td><td>Visual Initial Point / Visual Reference Point der F-16</td></tr><tr><td><strong>DDM / DMS / DD / MGRS</strong></td><td>Koordinatenformate: Grad-Dezimalminuten, Grad-Minuten-Sekunden, Dezimalgrad, Military Grid</td></tr><tr><td><strong>L / Z</strong></td><td>Ortszeit (Local) / Zulu (UTC)</td></tr></tbody></table><h2 id="taktische-grafiken" tabindex="-1">Taktische Grafiken <a class="header-anchor" href="#taktische-grafiken" aria-label="Permalink to &quot;Taktische Grafiken&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kürzel</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>CAP</strong></td><td>Combat Air Patrol – Racetrack-Station</td></tr><tr><td><strong>AR</strong></td><td>Air Refueling Track – Tanker-Bahn</td></tr><tr><td><strong>FLOT</strong></td><td>Forward Line of Own Troops</td></tr><tr><td><strong>FLET</strong></td><td>Forward Line of Enemy Troops</td></tr><tr><td><strong>FEBA</strong></td><td>Forward Edge of the Battle Area</td></tr><tr><td><strong>FSCL</strong></td><td>Fire Support Coordination Line</td></tr><tr><td><strong>CFL / NFL / RFL</strong></td><td>Coordinated / No / Restrictive Fire Line</td></tr><tr><td><strong>PL / LD / BDY</strong></td><td>Phase Line / Line of Departure / Boundary</td></tr><tr><td><strong>KB</strong></td><td>Kill Box</td></tr><tr><td><strong>ROZ</strong></td><td>Restricted Operations Zone</td></tr><tr><td><strong>NFA / RFA</strong></td><td>No-Fire / Restrictive Fire Area</td></tr><tr><td><strong>MRR</strong></td><td>Minimum Risk Route</td></tr><tr><td><strong>IP / CP</strong></td><td>Initial Point / Contact Point</td></tr></tbody></table><h2 id="aufgaben" tabindex="-1">Aufgaben <a class="header-anchor" href="#aufgaben" aria-label="Permalink to &quot;Aufgaben&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kürzel</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>SWEEP</strong></td><td>Offensiver Jagdvorstoß</td></tr><tr><td><strong>ESCORT / HVAAE</strong></td><td>Begleitschutz / Schutz hochwertiger Luftfahrzeuge (AWACS, Tanker)</td></tr><tr><td><strong>BARCAP / TARCAP / DCA</strong></td><td>Sperr-CAP / CAP über dem Ziel / Defensive Counter Air</td></tr><tr><td><strong>STRIKE / AI / OCA-AF</strong></td><td>Angriff / Abriegelung / Angriff auf Flugplätze</td></tr><tr><td><strong>CAS / SCAR / FACA</strong></td><td>Luftnahunterstützung / Strike Coordination &amp; Recce / Fliegender Fliegerleitoffizier</td></tr><tr><td><strong>SEAD / DEAD</strong></td><td>Niederhalten bzw. Zerstören der Luftabwehr</td></tr><tr><td><strong>EA / AEW / RECCE</strong></td><td>Elektronischer Kampf / Frühwarnung / Aufklärung</td></tr></tbody></table><h2 id="luftverteidigung" tabindex="-1">Luftverteidigung <a class="header-anchor" href="#luftverteidigung" aria-label="Permalink to &quot;Luftverteidigung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>IADS</strong></td><td>Integrated Air Defense System – vernetzte Luftverteidigung</td></tr><tr><td><strong>SAM</strong></td><td>Surface-to-Air Missile – Flugabwehrraketenstellung</td></tr><tr><td><strong>SHORAD</strong></td><td>Short Range Air Defense – Nahbereichsschutz</td></tr><tr><td><strong>EWR</strong></td><td>Early Warning Radar – Frühwarnradar</td></tr><tr><td><strong>AAA / MANPADS</strong></td><td>Flak / schultergestützte Flugabwehr</td></tr><tr><td><strong>CP / CN / PP</strong></td><td>Command Post / Connection Node / Power Plant im IADS</td></tr><tr><td><strong>EMCON</strong></td><td>Emission Control – wann ein Radar sendet</td></tr><tr><td><strong>God-View</strong></td><td>Alles wissen, was in der Mission steht – gibt es in Shardwing nicht</td></tr></tbody></table>',14)])])}const b=r(i,[["render",a]]);export{h as __pageData,b as default};
